// Hold the shophouse spine rollup to the per-building file it claims to come from.
//
// WHY THIS EXISTS. app/data/shophouse-spine-index.ts opens with "GENERATED by
// scripts/build-shophouse-spine.py — do not edit by hand." The generator
// cannot re-run here: it reads theses from /tmp and Treasury polygons from a
// sibling repo. But its OUTPUT is committed, twice — the per-building JSON
// and the TypeScript rollup — and a rollup nobody compares to its source is
// how PRESSURE_TOTAL sat at 2,311 after the screen had grown to 2,433.
//
// This verifies rather than regenerates. The editorial fields on each cluster
// (note, period, typology) are written by a person and must survive. The
// numeric half must not drift from shophouse-spine.json again.
//
// Runs as part of `npm run build` (data:spine).

import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { CLUSTER_RECORDS, SPINE_TOTAL } from "../app/data/shophouse-spine-index.ts";
import { PRESSURE_TOTAL } from "../app/data/shophouse-pressure.ts";

const here = dirname(fileURLToPath(import.meta.url));
const SPINE = resolve(here, "../public/data/shophouse-spine.json");
const summary = JSON.parse(
  readFileSync(resolve(here, "../app/data/rowhouse-footprint-summary.json"), "utf8"),
);

const rows = JSON.parse(readFileSync(SPINE, "utf8"));
const problems = [];
function expect(label, actual, published) {
  if (actual !== published) {
    problems.push(`  ${label}\n      published ${published}\n      actual    ${actual}`);
  }
}

expect("SPINE_TOTAL vs spine.json", rows.length, SPINE_TOTAL);
expect("SPINE_TOTAL vs PRESSURE_TOTAL", PRESSURE_TOTAL, SPINE_TOTAL);
expect("SPINE_TOTAL vs footprint summary", summary.candidate_count, SPINE_TOTAL);
expect(
  "CLUSTER_RECORDS n sum",
  CLUSTER_RECORDS.reduce((n, c) => n + c.n, 0),
  SPINE_TOTAL,
);

const byCluster = new Map();
for (const row of rows) {
  const slug = row.cluster || "unclustered";
  byCluster.set(slug, (byCluster.get(slug) || 0) + 1);
}
for (const cluster of CLUSTER_RECORDS) {
  expect(`${cluster.slug}.n`, byCluster.get(cluster.slug) ?? 0, cluster.n);
}
for (const slug of byCluster.keys()) {
  if (!CLUSTER_RECORDS.some((c) => c.slug === slug)) {
    problems.push(`  spine.json contains cluster ${slug}, which CLUSTER_RECORDS omits`);
  }
}

if (problems.length) {
  console.error(
    `verify-shophouse-spine: ${problems.length} published figure(s) disagree with\n` +
      `public/data/shophouse-spine.json (${rows.length} buildings):\n\n` +
      problems.join("\n") +
      `\n\nRe-run scripts/build-shophouse-spine.py rather than editing the rollup.\n`,
  );
  process.exit(1);
}

console.log(
  `verify-shophouse-spine: ${rows.length} buildings · ${CLUSTER_RECORDS.length} clusters · ` +
    `matches pressure ${PRESSURE_TOTAL} and footprint summary ${summary.candidate_count}`,
);
